import { requestCreditPreview, isCreditPreviewApiEnabled } from "./creditPreviewClient";

// The cost shown before a TEXT draft (BG-STUDIO-021-FE). Text is generated by the existing synchronous route, which accepts no quote, so it is never
// shown a binding quote it could not honour: only the backend's read-only preview, labelled as such. Image and video use the real quote/confirm flow in
// `QuotedGeneration.jsx` (generationQuoteClient.js).
export const costCheckAvailable = (env = import.meta.env) => isCreditPreviewApiEnabled(env);

export function requestCostCheck({ apiBaseUrl, accessToken, scope, executionClass = "text.standard", fetchImpl }) {
  return requestCreditPreview({ apiBaseUrl, accessToken, scope, executionClass, ...(fetchImpl ? { fetchImpl } : {}) });
}
